package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.ParseErrorList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Cleaner_isValid_TriageGen0Test {

    private Cleaner cleaner;
    private Whitelist whitelist;

    @Before
    public void setUp() {
        // Using basic whitelist that allows <a> and <p>
        whitelist = Whitelist.basic();
        cleaner = new Cleaner(whitelist);
    }

    @Test
    public void testIsValid_WithCleanDocument_ReturnsTrue() {
        String html = "<html><head></head><body><p>Hello World</p><a>Link</a></body></html>";
        Document dirtyDocument = Parser.parse(html);

        boolean result = cleaner.isValid(dirtyDocument);

        assertTrue("Document with allowed tags should be valid", result);
    }

    @Test
    public void testIsValid_WithDirtyDocument_ReturnsFalse() {
        // <script> is not in the basic whitelist
        String html = "<html><head></head><body><p>Safe</p><script>alert('xss')</script></body></html>";
        Document dirtyDocument = Parser.parse(html);

        boolean result = cleaner.isValid(dirtyDocument);

        assertFalse("Document with disallowed tags should be invalid", result);
    }

    @Test
    public void testIsValid_WithEmptyBody_ReturnsTrue() {
        String html = "<html><head></head><body></body></html>";
        Document dirtyDocument = Parser.parse(html);

        boolean result = cleaner.isValid(dirtyDocument);

        assertTrue("Empty body should be considered valid", result);
    }

    @Test
    public void testIsValid_WithAttributesNotAllowed_ReturnsFalse() {
        // 'onclick' is not allowed in basic whitelist
        String html = "<html><head></head><body><p onclick='bad()'>Text</p></body></html>";
        Document dirtyDocument = Parser.parse(html);

        boolean result = cleaner.isValid(dirtyDocument);

        assertFalse("Document with disallowed attributes should be invalid", result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsValid_WithNullDocument_ThrowsException() {
        cleaner.isValid(null);
    }

    @Test
    public void testIsValid_WithDeeplyNestedUnsafeTags_ReturnsFalse() {
        String html = "<html><head></head><body><div><p><div><script></script></div></p></div></body></html>";
        Document dirtyDocument = Parser.parse(html);

        boolean result = cleaner.isValid(dirtyDocument);

        assertFalse("Deeply nested unsafe tags should trigger invalid status", result);
    }
}
